/* Verifica a versão ao abrir/recarregar; somente a interface é renovada. */
(function(root){'use strict';const BUILD_VERSION='4.13.0';let updating=false;const retryKey='engefex-update-retry:'+location.pathname.replace(/[^/]+$/,'');
function recover(target){if(updating)return false;let last=null;try{last=JSON.parse(sessionStorage.getItem(retryKey)||'null')}catch{}if(last?.version===target&&Date.now()-last.time<60000)return true;try{sessionStorage.setItem(retryKey,JSON.stringify({version:target,time:Date.now()}))}catch{}updating=true;let label=document.getElementById('connectionStatus');if(label)label.textContent='Atualizando aplicativo…';location.replace('./recuperar-acesso.html?auto=1&target='+encodeURIComponent(target||BUILD_VERSION)+'&returnHash='+encodeURIComponent(location.hash||'#dashboard'));return false}
function newer(a,b){let x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<3;i++)if(x[i]!==y[i])return x[i]>y[i];return false}
async function check(){if(navigator.onLine===false)return true;let controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{let response=await fetch('./version.json?check='+Date.now(),{cache:'no-store',signal:controller.signal});if(response.ok){let meta=await response.json();if(/^\d+\.\d+\.\d+$/.test(meta.version||'')&&newer(meta.version,BUILD_VERSION))return recover(meta.version)}}catch{}finally{clearTimeout(timeout)}if(!('serviceWorker' in navigator))return true;try{const priorController=navigator.serviceWorker.controller,controlled=!!priorController,registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});await registration.update();if(controlled&&navigator.serviceWorker.controller!==priorController)return recover(BUILD_VERSION);let worker=registration.installing||registration.waiting;if(worker&&worker.state!=='activated'){await new Promise(resolve=>{let timer=setTimeout(resolve,15000);const changed=()=>{if(worker.state==='activated'||worker.state==='redundant'){clearTimeout(timer);worker.removeEventListener('statechange',changed);resolve()}};worker.addEventListener('statechange',changed);changed()});if(controlled&&worker.state==='activated')return recover(BUILD_VERSION)}}catch{}return true}
root.EngefexAutoUpdate={recover,get updating(){return updating},version:BUILD_VERSION};root.EngefexUpdateGate=check();
})(window);
